SET local check_function_bodies = off;

DROP POLICY "activity_entries_read" ON "better_supabase"."activity_entries";

DROP POLICY "bsb_tenant_scope_select" ON "better_supabase"."activity_entries";

CREATE TABLE "better_supabase"."risk_assessments" (
  "id"                  uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"           uuid                     NOT NULL,
  "risk_id"             uuid                     NOT NULL,
  "inherent_likelihood" integer                  NOT NULL,
  "inherent_impact"     integer                  NOT NULL,
  "inherent_score"      integer                  NOT NULL,
  "inherent_band"       text                     NOT NULL,
  "residual_likelihood" integer                  NOT NULL,
  "residual_impact"     integer                  NOT NULL,
  "residual_score"      integer                  NOT NULL,
  "residual_band"       text                     NOT NULL,
  "rationale"           text,
  "version_id"          uuid,
  "assessed_by"         uuid,
  "assessed_at"         timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "risk_assessments_inherent_impact_check" CHECK (((inherent_impact IS NULL) OR ((inherent_impact >= 1) AND (inherent_impact <= 10)))),
  CONSTRAINT "risk_assessments_inherent_likelihood_check" CHECK (((inherent_likelihood IS NULL) OR ((inherent_likelihood >= 1) AND (inherent_likelihood <= 10)))),
  CONSTRAINT "risk_assessments_inherent_score_check" CHECK (((inherent_score IS NULL) OR ((inherent_score >= 1) AND (inherent_score <= 100)))),
  CONSTRAINT "risk_assessments_pkey" PRIMARY KEY (id),
  CONSTRAINT "risk_assessments_rationale_check" CHECK (((rationale IS NULL) OR (length(rationale) <= 10000))),
  CONSTRAINT "risk_assessments_residual_impact_check" CHECK (((residual_impact IS NULL) OR ((residual_impact >= 1) AND (residual_impact <= 10)))),
  CONSTRAINT "risk_assessments_residual_likelihood_check" CHECK (((residual_likelihood IS NULL) OR ((residual_likelihood >= 1) AND (residual_likelihood <= 10)))),
  CONSTRAINT "risk_assessments_residual_score_check" CHECK (((residual_score IS NULL) OR ((residual_score >= 1) AND (residual_score <= 100))))
);

ALTER TABLE "better_supabase"."risk_assessments"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."risk_matrices" (
  "id"                uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"         uuid                     NOT NULL,
  "key"               text                     NOT NULL,
  "name"              text                     NOT NULL,
  "likelihood_levels" jsonb                    NOT NULL,
  "impact_levels"     jsonb                    NOT NULL,
  "bands"             jsonb                    NOT NULL,
  "scoring"           text                     NOT NULL DEFAULT 'product'::text,
  "is_default"        boolean                  NOT NULL DEFAULT false,
  "created_at"        timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"        timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "risk_matrices_bands_check" CHECK ((jsonb_typeof(bands) = 'array'::text)),
  CONSTRAINT "risk_matrices_impact_levels_check" CHECK ((jsonb_typeof(impact_levels) = 'array'::text)),
  CONSTRAINT "risk_matrices_key_check" CHECK ((key ~ '^[a-z][a-z0-9_-]{0,62}$'::text)),
  CONSTRAINT "risk_matrices_likelihood_levels_check" CHECK ((jsonb_typeof(likelihood_levels) = 'array'::text)),
  CONSTRAINT "risk_matrices_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "risk_matrices_pkey" PRIMARY KEY (id),
  CONSTRAINT "risk_matrices_scoring_check" CHECK ((scoring = ANY (ARRAY['product'::text, 'sum'::text]))),
  CONSTRAINT "risk_matrices_tenant_id_id_key" UNIQUE (tenant_id, id),
  CONSTRAINT "risk_matrices_tenant_id_key_key" UNIQUE (tenant_id, key)
);

ALTER TABLE "better_supabase"."risk_matrices"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."risks" (
  "id"                     uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"              uuid                     NOT NULL,
  "number"                 text                     NOT NULL,
  "sequence"               bigint                   NOT NULL,
  "matrix_id"              uuid                     NOT NULL,
  "title"                  text                     NOT NULL,
  "description"            text,
  "category"               text                     NOT NULL,
  "cause"                  text,
  "consequence"            text,
  "owner_id"               uuid,
  "status"                 text                     NOT NULL DEFAULT 'identified'::text,
  "treatment"              text,
  "review_interval_months" integer,
  "next_review_on"         date,
  "reviewed_at"            timestamp with time zone,
  "review_notified_for"    date,
  "inherent_likelihood"    integer,
  "inherent_impact"        integer,
  "inherent_score"         integer,
  "inherent_band"          text,
  "residual_likelihood"    integer,
  "residual_impact"        integer,
  "residual_score"         integer,
  "residual_band"          text,
  "current_assessment_id"  uuid,
  "closed_at"              timestamp with time zone,
  "archived_at"            timestamp with time zone,
  "created_by"             uuid,
  "created_at"             timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"             timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "risks_category_check" CHECK (((length(category) >= 1) AND (length(category) <= 63))),
  CONSTRAINT "risks_cause_check" CHECK (((cause IS NULL) OR (length(cause) <= 4000))),
  CONSTRAINT "risks_check" CHECK (((status <> 'closed'::text) OR (closed_at IS NOT NULL))),
  CONSTRAINT "risks_consequence_check" CHECK (((consequence IS NULL) OR (length(consequence) <= 4000))),
  CONSTRAINT "risks_description_check" CHECK (((description IS NULL) OR (length(description) <= 10000))),
  CONSTRAINT "risks_inherent_impact_check" CHECK (((inherent_impact IS NULL) OR ((inherent_impact >= 1) AND (inherent_impact <= 10)))),
  CONSTRAINT "risks_inherent_likelihood_check" CHECK (((inherent_likelihood IS NULL) OR ((inherent_likelihood >= 1) AND (inherent_likelihood <= 10)))),
  CONSTRAINT "risks_inherent_score_check" CHECK (((inherent_score IS NULL) OR ((inherent_score >= 1) AND (inherent_score <= 100)))),
  CONSTRAINT "risks_number_check" CHECK (((length(number) >= 1) AND (length(number) <= 100))),
  CONSTRAINT "risks_pkey" PRIMARY KEY (id),
  CONSTRAINT "risks_residual_impact_check" CHECK (((residual_impact IS NULL) OR ((residual_impact >= 1) AND (residual_impact <= 10)))),
  CONSTRAINT "risks_residual_likelihood_check" CHECK (((residual_likelihood IS NULL) OR ((residual_likelihood >= 1) AND (residual_likelihood <= 10)))),
  CONSTRAINT "risks_residual_score_check" CHECK (((residual_score IS NULL) OR ((residual_score >= 1) AND (residual_score <= 100)))),
  CONSTRAINT "risks_review_interval_months_check" CHECK (((review_interval_months IS NULL) OR ((review_interval_months >= 1) AND (review_interval_months <= 120)))),
  CONSTRAINT "risks_status_check" CHECK ((status = ANY (ARRAY['identified'::text, 'assessed'::text, 'treating'::text, 'accepted'::text, 'closed'::text]))),
  CONSTRAINT "risks_tenant_id_id_key" UNIQUE (tenant_id, id),
  CONSTRAINT "risks_tenant_id_number_key" UNIQUE (tenant_id, number),
  CONSTRAINT "risks_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 300))),
  CONSTRAINT "risks_treatment_check" CHECK (((treatment IS NULL) OR (treatment = ANY (ARRAY['mitigate'::text, 'accept'::text, 'transfer'::text, 'avoid'::text]))))
);

ALTER TABLE "better_supabase"."risks"
  ENABLE ROW LEVEL SECURITY;

